/* Unattended workflow prototype only: no OCR, face recognition, mail, SMS or charges.
   Licence previews are ephemeral and never copied to Vault/localStorage. */
let checkinDraft=null,licencePreview='',licenceLoadVersion=0;
function autoState(){if(!state.unattended)state.unattended={visits:[],outbox:[],incidents:[],emergency:{name:'',email:'',enabled:true}};return state.unattended}
const autoVisit=id=>autoState().visits.find(v=>v.id===id);
const autoLabel=v=>({checked_in:'Checked in · awaiting arrival',in_yard:'In yard · awaiting departure',completed:'Weighed out',exception:'Needs remote review'}[v.status]||v.status);
function openUnattended(){close();autoState();go('unattended');renderUnattended()}
function renderUnattended(){
 const a=autoState();$('unattended').innerHTML='<div class="vault-top"><button class="text-button" data-page="equipment">← Equipment & settings</button><div><button class="button" data-auto="emergency">Emergency contact</button><button class="button primary" data-auto="driver">Driver QR check-in →</button></div></div>'+(state.settings.mode!=='live'?'<div class="callout amber">Manual mode · unattended actions are paused. Existing visits and billing records are kept. <button class="button" data-station-mode="live">Enable Auto mode</button></div>':'')+'<div class="callout">Interactive simulation: open the driver check-in as if a yard QR code brought you here. Licence extraction, camera verification, emails and payments are simulated. No real licence is needed.</div>'+(!a.emergency.email?'<div class="vault-error">No emergency email configured. Incidents will be recorded but have no email recipient. <button class="text-button" data-auto="emergency">Set emergency contact →</button></div>':'')+'<div class="history-summary"><div class="summary-box"><span>Active visits</span><strong>'+a.visits.filter(v=>v.status!=='completed').length+'</strong></div><div class="summary-box"><span>Needs remote review</span><strong>'+a.incidents.filter(i=>!i.resolved).length+'</strong></div><div class="summary-box"><span>Email previews</span><strong>'+a.outbox.length+'</strong></div></div><section class="panel"><div class="panel-heading"><div><h2>Driver visits</h2><p>Each driver checks in and supplies a licence on every visit.</p></div><button class="text-button" data-auto="driver">＋ New check-in</button></div><div class="auto-visits">'+(a.visits.length?a.visits.slice().reverse().map(v=>{const t=getTicket(v.ticketId);return '<article class="auto-visit"><div class="vault-row-heading"><div><strong>'+esc(v.plate)+'</strong><span>'+esc(v.driver)+' · '+esc(v.customer||'Walk-in')+'</span></div><span class="pill '+(v.status==='completed'?'good':v.status==='exception'?'bad':'')+'">'+autoLabel(v)+'</span></div><p>'+esc(v.material)+' · '+esc(v.vehicle)+' · '+esc(v.colour)+'</p><small>'+new Date(v.createdAt).toLocaleString('en-CA',{timeZone:'America/Edmonton'})+' · '+(v.account?'Approved demo account · invoice':'Walk-in · payment link')+'</small>'+(t?'<div class="detail-grid"><div><small>IN</small><strong>'+fmt(t.gross)+' kg</strong></div><div><small>OUT</small><strong>'+(t.tare?fmt(t.tare)+' kg':'—')+'</strong></div><div><small>NET</small><strong>'+(t.tare?fmt(net(t))+' kg':'—')+'</strong></div></div>':'')+'<div class="auto-visit-actions"><button class="button" data-auto-detail="'+v.id+'">Visit details</button>'+(v.status==='checked_in'||v.status==='in_yard'?'<button class="button primary" data-auto-weigh="'+v.id+'">Simulate '+(v.status==='checked_in'?'arrival':'departure')+' →</button><button class="text-button" data-auto-issue="'+v.id+'">Try an exception</button>':v.status==='exception'?'<button class="button" data-auto-resolve="'+v.id+'">Review exception</button>':'<button class="button primary" data-auto-email="'+v.id+'">'+(v.account?'View invoice email':'View payment email')+'</button>')+'</div></article>'}).join(''):'<div class="empty">Start with Driver QR check-in. Check in two drivers to try multiple trucks in the yard.</div>')+'</div></section><section class="panel" style="margin-top:22px"><div class="panel-heading"><h2>Email outbox · previews only</h2><span class="muted">SMS coming later</span></div>'+a.outbox.slice().reverse().map(m=>'<button class="payment-summary-row auto-mail" data-auto-message="'+m.id+'"><span>'+esc(m.subject)+'<small>To: '+esc(m.to||'No recipient configured')+' · '+new Date(m.at).toLocaleTimeString('en-CA')+'</small></span><span class="pill '+(m.to?'':'bad')+'">'+(m.to?'Preview only':'Recipient needed')+' →</span></button>').join('')+(!a.outbox.length?'<div class="empty">Invoice, payment and emergency email previews appear here.</div>':'')+'</section>';
 if(state.settings.mode!=='live')document.querySelectorAll('#unattended [data-auto=driver],#unattended [data-auto-weigh],#unattended [data-auto-issue],#unattended [data-auto-resolve]').forEach(b=>b.disabled=true);
}
function startDriver(){if(!requireAuto())return;licencePreview='';licenceLoadVersion++;checkinDraft={extracted:false};modal('Welcome to the yard','<div class="auto-step">1 · Driver check-in &nbsp; → &nbsp; 2 · Licence &nbsp; → &nbsp; 3 · Confirm visit</div><p class="modal-intro">This is the mobile form a driver would open from the yard QR sign.</p><form id="driver-start"><label class="field">Customer type<select name="account"><option value="walkin">Walk-in / new customer</option><option value="registered">Registered account customer</option></select></label><p class="settings-note">Registered accounts are pre-approved demo accounts. Production must authenticate account access and verify invoicing eligibility.</p>'+actions('<button class="button primary" type="submit">Continue →</button>')+'</form>','DRIVER PHONE PREVIEW')}
function driverLicence(){modal('Licence for this visit','<div class="auto-step">Step 2 of 3 · Required every visit</div><p class="modal-intro">Use the sample licence to try extraction. Please do not upload a real driver’s licence to this demo.</p><button class="choice" data-auto="sample-licence"><span>▣</span><div><strong>Use sample driver’s licence</strong><small>Fictional driver · no personal document required</small></div><span class="arrow">→</span></button><label class="field">Or attach a sample licence picture<input id="auto-licence-file" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG / PNG / WebP under 20 MB. Preview stays in memory and is discarded when you leave this flow.</small></label><div id="auto-licence-preview" hidden></div><p id="auto-licence-error" role="alert" class="printer-error"></p><div class="callout">This prototype returns fictional extracted fields. It does not read or authenticate your uploaded document, compare faces, or send it anywhere.</div><div class="modal-actions"><button class="button" data-auto="driver">Back</button><button id="auto-extract" class="button primary" data-auto="extract" disabled>Simulate information extraction →</button></div>','DRIVER PHONE PREVIEW')}
function useSampleLicence(){licenceLoadVersion++;licencePreview='sample';$('auto-licence-preview').hidden=false;$('auto-licence-preview').innerHTML='<div class="sample-licence"><span>DEMO LICENCE · NOT VALID ID</span><strong>Alex Morgan</strong><small>Expiry: 2028-12-31<br>Fictional sample for this visit only</small></div>';$('auto-extract').disabled=false;$('auto-licence-error').textContent=''}
function driverConfirm(){if(!licencePreview)return;checkinDraft.extracted=true;modal('Confirm your visit','<div class="auto-step">Step 3 of 3 · Check the extracted information</div><div class="callout">Sample extraction complete. Correct any details before continuing. Vehicle cameras will verify the plate at the scale.</div><form id="driver-confirm">'+(checkinDraft.account?'<label class="field">Approved demo account<select name="customer">'+state.customers.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select></label>':'<label class="field">Company / customer name<input name="customer" maxlength="120" placeholder="Optional"></label>')+'<div class="form-grid"><label class="field">Driver name · extracted<input name="driver" required maxlength="100" value="Alex Morgan"></label><label class="field">Licence expiry · extracted<input name="expiry" type="date" required value="2028-12-31"></label></div><label class="field">Email for '+(checkinDraft.account?'invoice':'payment link')+'<input name="email" type="email" required maxlength="160" placeholder="driver@example.com"><small>Email previews only in this demo.</small></label><div class="form-grid"><label class="field">Licence plate #<input name="plate" required maxlength="20" placeholder="e.g. BTR 4821"></label><label class="field">Material<select name="material">'+state.materials.map((m,i)=>'<option value="'+i+'">'+esc(m.name)+'</option>').join('')+'</select></label></div><div class="form-grid"><label class="field">Vehicle<input name="vehicle" required maxlength="100" placeholder="e.g. Kenworth dump truck"></label><label class="field">Colour<input name="colour" required maxlength="40" placeholder="e.g. White"></label></div><label class="toggle-row"><span>I have checked the extracted details and agree to receive this visit’s billing email.<small>This is a demo confirmation, not a production agreement.</small></span><input name="confirmed" type="checkbox" required></label>'+actions('<button class="button primary" type="submit">Check in →</button>')+'</form>','DRIVER PHONE PREVIEW')}
function autoWeigh(id){if(!requireAuto())return;const v=autoVisit(id);if(!v||!['checked_in','in_yard'].includes(v.status))return;const incoming=v.status==='checked_in';modal(incoming?'Truck arriving at the scale':'Truck leaving the yard','<p class="modal-intro">'+esc(v.driver)+' · '+esc(v.plate)+' · '+esc(v.material)+'</p><form id="auto-weigh-form" data-visit="'+id+'"><div class="callout">Simulates a stable scale reading and a camera plate observation. Only the selected visit is affected.</div><label class="field">Observed plate from camera<input name="observedPlate" required value="'+esc(v.plate)+'" maxlength="20"></label><label class="field">Stable '+(incoming?'inbound':'outbound')+' weight (kg)<input name="weight" type="number" min="1" max="100000" required value="'+(incoming?'18420':'7860')+'"></label><label class="toggle-row"><span>Reading is stable<small>Unstable, disconnected or mismatched observations require review.</small></span><input name="stable" type="checkbox" checked></label>'+actions('<button class="button primary" type="submit">Simulate automatic '+(incoming?'weigh-in':'weigh-out')+'</button>')+'</form>','AUTONOMOUS FLOW · DEMO')}
function autoEmail(kind,to,subject,body,visit){const msg={id:crypto.randomUUID(),kind,to,subject,body,visit,at:new Date().toISOString()};autoState().outbox.push(msg);return msg}
function autoIncident(v,reason){if(!requireAuto())return;const a=autoState();if(v.status!=='exception')v.previousStatus=v.status;v.status='exception';const incident={id:crypto.randomUUID(),visit:v.id,reason,at:new Date().toISOString(),resolved:false};a.incidents.push(incident);const c=a.emergency;if(c.enabled)autoEmail('emergency',c.email,'Station 01: '+reason,'A visit needs remote review.\nPlate: '+v.plate+'\nDriver: '+v.driver+'\nVisit: '+v.id+'\nIssue: '+reason+'\nNo further weighing or billing was completed by this event.',v.id);save();close();openUnattended();toast(c.enabled&&c.email?'Exception saved. Emergency email preview created.':'Exception saved. Emergency email is disabled or missing.');}
function autoReview(id){const v=autoVisit(id),issues=autoState().incidents.filter(i=>i.visit===id&&!i.resolved);modal('Remote review','<p class="modal-intro">'+esc(v.plate)+' · '+esc(v.driver)+'</p>'+issues.map(i=>'<div class="callout amber" style="margin-bottom:10px">'+esc(i.reason)+'</div>').join('')+'<form id="auto-resolve-form" data-visit="'+id+'"><label class="field">Resolution notes<textarea name="reason" required maxlength="2000" placeholder="What was checked or corrected?"></textarea></label><p class="settings-note">Resolving returns the visit to its previous step. It does not bypass the next weight or plate check.</p>'+actions('<button class="button primary" type="submit">Resolve and retry</button>')+'</form>','EMERGENCY CONTACT WORKSPACE')}
function emergencySettings(){const c=autoState().emergency;modal('Emergency contact','<p class="modal-intro">Who should be notified when an unattended visit needs help?</p><form id="emergency-form"><label class="field">Contact name<input name="name" required maxlength="100" value="'+esc(c.name)+'" placeholder="On-call operator"></label><label class="field">Email address<input name="email" type="email" required maxlength="160" value="'+esc(c.email)+'" placeholder="operator@example.com"></label><label class="toggle-row"><span>Email alerts enabled<small>Plate mismatch, missing camera or invalid scale reading.</small></span><input name="enabled" type="checkbox" '+(c.enabled?'checked':'')+'></label><div class="callout" style="margin-top:18px">Email first. SMS is planned for later. Alerts in this prototype are previews and are never sent.</div>'+actions('<button class="button primary" type="submit">Save emergency contact</button>')+'</form>','UNATTENDED SETTINGS')}
function autoMessage(id){const m=autoState().outbox.find(m=>m.id===id);if(!m)return;const v=autoVisit(m.visit);modal('Email preview','<div class="callout">Not sent · demonstration only</div><div class="detail-list"><div><span>To</span><strong>'+esc(m.to||'No recipient configured')+'</strong></div><div><span>Subject</span><strong>'+esc(m.subject)+'</strong></div></div><div class="auto-email-body">'+esc(m.body)+'</div><div class="modal-actions"><button class="button" data-action="close">Close</button>'+(m.kind==='invoice'?'<button class="button primary" data-auto-invoice="'+v.id+'">Open invoice</button>':m.kind==='payment'?'<button class="button primary" data-auto-pay="'+v.id+'">Open payment link</button>':v&&v.status==='exception'?'<button class="button primary" data-auto-resolve="'+v.id+'">Review incident</button>':'')+'</div>','EMAIL DELIVERY · SIMULATED')}
function autoInvoice(id){const v=autoVisit(id),t=getTicket(v.ticketId);modal('Invoice '+v.invoiceNumber,'<div class="callout">Approved account · payment due '+esc(v.dueDate)+'</div><div class="detail-list">'+[['Customer',v.customer],['Email',v.email],['Driver',v.driver],['Plate',v.plate],['Material',t.material],['Net',fmt(net(t))+' kg'],['Subtotal',money(net(t)*t.rate)],['GST',money(net(t)*t.rate*.05)],['Total CAD',money(total(t))],['Payment status',t.payment==='unpaid'?'Unpaid':t.payment]].map(([k,val])=>'<div><span>'+k+'</span><strong>'+esc(val)+'</strong></div>').join('')+'</div><p class="settings-note">Demo invoice: 30-day terms. Production must use the account’s approved terms and server-issued invoice.</p><div class="modal-actions"><button class="button" data-action="close">Close</button><button class="button primary" data-auto-pay="'+v.id+'">Pay sample invoice</button></div>','ACCOUNT BILLING')}
function autoVisitDetail(id){const v=autoVisit(id);modal('Visit '+v.plate,'<div class="detail-list">'+[['Status',autoLabel(v)],['Driver',v.driver],['Customer',v.customer||'Walk-in'],['Email',v.email],['Vehicle',v.vehicle],['Colour',v.colour],['Material',v.material],['Licence',v.licenceStatus+' · this visit'],['Licence expiry',v.expiry],['Billing',v.account?'Approved account invoice':'Email payment link'],['Visit ID',v.id]].map(([k,val])=>'<div><span>'+k+'</span><strong>'+esc(val)+'</strong></div>').join('')+'</div><p class="settings-note">No licence image or licence number is stored in the prototype or Photo Vault. Licence extraction and verification are simulated.</p><div class="modal-actions"><button class="button" data-action="close">Close</button>'+(v.ticketId?'<button class="button" data-ticket="'+v.ticketId+'">Open scale ticket</button>':'')+'<button class="button" data-auto="vault">Photo Vault</button></div>','DRIVER VISIT')}
document.addEventListener('change',e=>{if(e.target.id!=='auto-licence-file')return;const file=e.target.files[0];licencePreview='';const version=++licenceLoadVersion;$('auto-extract').disabled=true;$('auto-licence-preview').hidden=true;if(!file)return;if(file.size>=20*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){$('auto-licence-error').textContent='Choose a JPG, PNG or WebP under 20 MB.';return;}const reader=new FileReader();reader.onload=()=>{if(version!==licenceLoadVersion||!$('auto-licence-preview'))return;licencePreview=String(reader.result);$('auto-licence-preview').innerHTML='<img class="licence-preview" alt="Temporary sample licence preview" src="'+esc(licencePreview)+'">';$('auto-licence-preview').hidden=false;$('auto-extract').disabled=false;$('auto-licence-error').textContent='Preview loaded. Extraction will still use fictional sample data.';};reader.onerror=()=>{if($('auto-licence-error'))$('auto-licence-error').textContent='Cannot read this file. Try the sample licence.';};reader.readAsDataURL(file);});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.autoWeigh)return autoWeigh(b.dataset.autoWeigh);if(b.dataset.autoDetail)return autoVisitDetail(b.dataset.autoDetail);if(b.dataset.autoResolve)return autoReview(b.dataset.autoResolve);if(b.dataset.autoIssue)return autoIncident(autoVisit(b.dataset.autoIssue),'Camera plate could not be confidently matched');if(b.dataset.autoMessage)return autoMessage(b.dataset.autoMessage);if(b.dataset.autoEmail){const m=autoState().outbox.filter(m=>m.visit===b.dataset.autoEmail&&['invoice','payment'].includes(m.kind)).at(-1);if(m)autoMessage(m.id);return}if(b.dataset.autoInvoice)return autoInvoice(b.dataset.autoInvoice);if(b.dataset.autoPay){const v=autoVisit(b.dataset.autoPay),t=getTicket(v.ticketId);return autoCheckout(v.id)}switch(b.dataset.auto){case'open':openUnattended();break;case'driver':startDriver();break;case'emergency':emergencySettings();break;case'sample-licence':useSampleLicence();break;case'extract':driverConfirm();break;case'vault':close();openVault();break;}});
document.addEventListener('submit',e=>{
 const form=e.target;if(!['driver-start','driver-confirm','auto-weigh-form','emergency-form','auto-resolve-form'].includes(form.id))return;e.preventDefault();if(['driver-start','driver-confirm','auto-weigh-form','auto-resolve-form'].includes(form.id)&&!requireAuto())return;const d=new FormData(form),a=autoState();
 if(form.id==='driver-start'){checkinDraft.account=d.get('account')==='registered';driverLicence();}
 if(form.id==='emergency-form'){a.emergency={name:String(d.get('name')).trim(),email:String(d.get('email')).trim(),enabled:d.has('enabled')};save();close();toast('Emergency contact saved. Email alerts are simulated.');}
 if(form.id==='driver-confirm'){
 if(!checkinDraft?.extracted||!licencePreview)return toast('A licence is required for this visit.');
 const plate=String(d.get('plate')).trim().toUpperCase();if(!normalizePlate(plate))return toast('Enter a valid plate.');
 if(a.visits.some(v=>v.status!=='completed'&&normalizePlate(v.plate)===normalizePlate(plate)))return toast('This plate already has an active visit. Ask the emergency contact to review it.');
 const expiry=String(d.get('expiry'));if(expiry<vaultDate(new Date().toISOString()))return toast('The licence appears expired. Correct the date or contact the emergency contact.');
 const m=state.materials[Number(d.get('material'))],v={id:crypto.randomUUID(),createdAt:new Date().toISOString(),status:'checked_in',account:checkinDraft.account,driver:String(d.get('driver')).trim(),email:String(d.get('email')).trim(),customer:String(d.get('customer')).trim(),plate,vehicle:String(d.get('vehicle')).trim(),colour:String(d.get('colour')).trim(),material:m.name,rate:m.rate,expiry,licenceStatus:'Sample extraction confirmed',ticketId:null};a.visits.push(v);licencePreview='';licenceLoadVersion++;checkinDraft=null;save();close();openUnattended();toast('Checked in. Drive onto the scale for the arrival simulation.');}
 if(form.id==='auto-weigh-form'){
 const v=autoVisit(form.dataset.visit);if(!v||!['checked_in','in_yard'].includes(v.status))return;
 const observed=normalizePlate(d.get('observedPlate')),weight=Number(d.get('weight'));
 if(!state.connected)return autoIncident(v,'Scale disconnected');if(!d.has('stable'))return autoIncident(v,'Scale reading is not stable');ensureCameras();if(!state.cameras.some(c=>c.enabled))return autoIncident(v,'No camera available for vehicle verification');
 if(observed!==normalizePlate(v.plate))return autoIncident(v,'Camera plate does not match check-in');if(!Number.isFinite(weight)||weight<=0||weight>100000)return autoIncident(v,'Invalid scale weight');
 if(v.status==='checked_in'){
 const t={id:state.nextId++,vaultVisit:v.id,customer:v.customer,driver:v.driver,plate:v.plate,vehicle:v.vehicle,colour:v.colour,phone:'',material:v.material,rate:v.rate,gross:weight,tare:0,status:'open',date:TODAY,time:new Date().toLocaleTimeString('en-CA',{hour:'2-digit',minute:'2-digit',hour12:false}),payment:'unpaid',notes:'Unattended demo visit '+v.id,type:'dropoff'};state.tickets.push(t);v.ticketId=t.id;v.status='in_yard';v.arrivedAt=new Date().toISOString();captureTicketVault(t,'in');save();close();openUnattended();toast('Arrival verified. Inbound weight and sample photos captured.');
 }else{
 const t=getTicket(v.ticketId);if(!t||t.status!=='open')return autoIncident(v,'Ticket is no longer open');if(weight>=t.gross)return autoIncident(v,'Outbound weight is not below inbound weight');
 t.tare=weight;t.status='completed';v.status='completed';v.departedAt=new Date().toISOString();state.settled=false;captureTicketVault(t,'out');
 if(v.account){v.invoiceNumber='DEMO-INV-'+t.id;v.dueDate=vaultDate(new Date(Date.now()+30*86400000).toISOString());autoEmail('invoice',v.email,'Invoice '+v.invoiceNumber+' · '+brandValue().name,'Your load is complete.\nTicket: '+ticketNumber(t)+'\nPlate: '+v.plate+'\nNet weight: '+fmt(net(t))+' kg\nTotal: '+money(total(t))+' CAD\nDue: '+v.dueDate+'\nOpen the sample invoice below. Departure is allowed; payment remains due.',v.id);}else{autoEmail('payment',v.email,'Payment requested · '+ticketNumber(t),'Your load is complete.\nPlate: '+v.plate+'\nNet weight: '+fmt(net(t))+' kg\nAmount due: '+money(total(t))+' CAD\nUse the sample payment-link button below. You may leave the yard; this balance remains unpaid until payment is recorded.',v.id);}
 save();close();openUnattended();toast('Weigh-out complete. Billing email preview created; balance remains unpaid.');}
 }
 if(form.id==='auto-resolve-form'){const v=autoVisit(form.dataset.visit),reason=String(d.get('reason')).trim();if(!reason)return;if(v.status!=='exception')return;for(const i of a.incidents.filter(i=>i.visit===v.id&&!i.resolved)){i.resolved=true;i.resolvedAt=new Date().toISOString();i.resolution=reason;}v.status=v.previousStatus||'checked_in';save();close();openUnattended();toast('Exception resolved. Retry the simulated scale event.');}
});

document.getElementById("modal").addEventListener("close",()=>{licencePreview="";checkinDraft=null;licenceLoadVersion++;});

function autoCheckout(id){const v=autoVisit(id),t=getTicket(v.ticketId);if(t.payment!=='unpaid')return receipt(t.id);modal('Pay for your visit','<p class="modal-intro">'+esc(v.plate)+' · '+ticketNumber(t)+'</p><div class="payment-total">'+money(total(t))+' CAD</div><div class="callout">Sample online checkout. No card details are collected and no money is charged.</div><p class="settings-note">In production, this link opens the payment provider’s secure checkout. Payment is confirmed by a verified server webhook.</p><div class="modal-actions"><button class="button" data-action="close">Pay later</button><button class="button primary" data-auto-charge="'+v.id+'">Simulate successful online payment</button></div>','DRIVER PAYMENT LINK')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-auto-charge]');if(!b)return;const v=autoVisit(b.dataset.autoCharge),t=getTicket(v.ticketId);if(t.payment!=='unpaid')return receipt(t.id);t.payment='card';state.settled=false;t.paidAt=new Date().toISOString();t.paymentReference='DEMO-ONLINE-'+t.id;t.paymentActivity=t.paymentActivity||[];t.paymentActivity.push({at:t.paidAt,operator:'Driver checkout demo',text:'Simulated online card payment recorded'});save();receipt(t.id);});
